-- mod-classic-classes: the start outfit of the race and class pairs the CoA data dresses only for show (a look of high
-- level armour without items) or not at all - the outfit of the same class and sex of another race, of the same faction
-- where there is one (the Orc Druid wears the Troll Druid's). Without it such a character would start without gear.
-- The ids are those of CoA's CharStartOutfit.dbc (October 2026); a row of this table takes the place of the row of the
-- DBC file with its id. The client patch of the module dresses the character creation the same way.

DELETE FROM `charstartoutfit_dbc` WHERE `ID` IN (13, 14, 23, 24, 29, 30, 57, 58, 63, 64, 73, 74, 77, 78, 93, 94, 107, 108, 109, 110, 115, 116, 117, 118, 123, 124, 125, 126, 133, 134, 143, 144, 193, 194, 207, 208, 217, 218, 981, 982, 983, 984, 985, 986, 989, 990, 993, 994, 999, 1000, 1001, 1002, 1023, 1024);
